const LeaderSelectLeadersPanel: Component = () => {
	const leaderModel = LeaderSelectModel.get();
	const flowContext = useScreenFlowContext();

	const isDesktop = createMemo(() => ViewExperience() == UIViewExperience.Desktop);
	const isSmallScreen = useIsSmallScreen();
	const showSearch = createMemo(() => !isSmallScreen() && !IsControllerActive() && isDesktop());

	// const recModel = RecommendedChoiceModel.get();
	const selectedLeaderId = createMemo(() => leaderModel.selectedLeader().leaderID);
	const isSelected = createSelector(selectedLeaderId);

	// TODO this should not be filtered by a string name
	const filterItems = ["LOC_LEGACIES_FILTER_ALL_ATTRIBUTES"];
	Database.query("config", "SELECT * FROM Tags WHERE TagCategoryType = 'TAG_CATEGORY_TRAIT'")?.forEach((tag) => {
		if (tag.Name) filterItems.push(tag.Name as string);
	});

	const [selectedFilter, setSelectedFilter] = createSignal<string | undefined>("LOC_LEGACIES_FILTER_ALL_ATTRIBUTES");
	const [textFilter, setTextFilter] = createSignal<string>("");
	let filterRef!: HTMLElement;

	const searchResults = createMemo(() =>
		textFilter() ? leaderModel.fulltextSearch(textFilter()) : new Set<string>(),
	);

	function filter(leader: LeaderInfo) {
		const hasText = !isDesktop() || !textFilter() || searchResults().has(leader.leaderID);
		const hasDropdown =
			selectedFilter() == "LOC_LEGACIES_FILTER_ALL_ATTRIBUTES" || leader.tags.some((t) => t == selectedFilter());
		return hasText && hasDropdown;
	}

	function handleLeaderSelect(leader: LeaderInfo) {
		if (IsControllerActive()) {
			flowContext.activateNext();
		} else {
			leaderModel.setSelectedLeader(leader);
		}
	}

	function handleLeaderFocus(leader: LeaderInfo) {
		if (IsControllerActive()) {
			leaderModel.setSelectedLeader(leader);
		}
	}

	const allLeaders = createMemo(() => leaderModel.leaders.filter(filter));
	const audio = useAudio("LeaderSelectScreen");
	onMount(() => {
		audio("popup-open");
	});

	return (
		<div class="leader-select-leaders-panel img-unit-panelbox flex flex-col relative justify-center">
			<Hotkeys
				hotkeys={[
					{
						hotkeyAction: "accept",
						navTrayText: "LOC_GENERIC_SELECT",
						onActivate: () => flowContext.activateNext(),
					},
					{
						hotkeyAction: "cancel",
						navTrayText: "LOC_GENERIC_BACK",
						onActivate: () => {
							flowContext.activatePrev();
							useAudio("CreateGameBackButton")("activate");

							//reset filters
							resetCivsFilters();
						},
					},
					{
						hotkeyAction: "shell-action-2",
						navTrayText: "LOC_UI_FILTER_SORT_FILTERS",
						onActivate: () => FocusManager.get().setFocus(filterRef),
					},
				]}
			/>

			<div class="leader-select-corner-filigree inner-top-left" />
			<div class="leader-select-corner-filigree inner-top-right" />
			<div
				class={`absolute right-0 -top-32 pointer-events-none opacity-50`}
				style={{
					width: Layout.pixels(565),
					height: Layout.pixels(400),
					"background-image": `url('blp:popup_icon_glow')`,
					"background-size": "100% 100%",
				}}
			/>
			<div class="mx-5 mb-1 mt-4 flex leader-select-filters-container">
				<Show when={showSearch()}>
					<AudioContextProvider segment="LeaderSelectScreen">
						<SearchBar
							value={textFilter}
							setValue={setTextFilter}
							class="ml-2 leader-select-filter-search"
						/>
					</AudioContextProvider>
				</Show>
				<AudioContextProvider segment="LeaderSelectFilter">
					<Dropdown
						selectedItemTemplate={(item) => (
							<span class="m-2">
								<L10n.Compose
									text="LOC_UI_CREATE_GAME_FILTER_ITEM"
									args={[Locale.toUpper(Locale.compose(item))]}
								/>
							</span>
						)}
						hotkey="shell-action-2"
						defaultValue={filterItems[0]}
						onItemSelected={(item) => setSelectedFilter(item)}
						disableFocus={true}
						class="mx-2 leader-select-filter-dropdown"
						ref={filterRef}
					>
						<For each={filterItems}>
							{(item) => <DropdownItem value={item}>{Locale.toUpper(Locale.compose(item))}</DropdownItem>}
						</For>
					</Dropdown>
				</AudioContextProvider>
			</div>
			<div class="leader-select-line-divider my-2" />
			<ScrollArea
				class={`flex-auto ${isMobile() ? "my-2 ml-2" : "m-2"}`}
				allowGamepadPan={false}
			>
				<SpatialSlot
					name="leader-list"
					class={`flex-auto flex flex-row flex-wrap ${isMobile() ? "pl-2" : "pl-4"} -mr-2`}
				>
					<For each={allLeaders()}>
						{(leader) => (
							<Tooltip.Text
								bodyClass="flex flex-row justify-center"
								text={leader.name}
							>
								<LeaderSelectButton
									leaderInfo={leader}
									isSelected={isSelected(leader.leaderID)}
									autoFocus={isSelected(leader.leaderID)}
									onActivate={() => handleLeaderSelect(leader)}
									onFocus={() => handleLeaderFocus(leader)}
								/>
							</Tooltip.Text>
						)}
					</For>
				</SpatialSlot>
			</ScrollArea>
			<Show when={!IsControllerActive()}>
				<div class="leader-select-decoration-bar">
					<div class="img-unit-panelbox mt-3 mb-4 mx-4 pt-3 pb-4 relative flex flex-row justify-center items-center">
						<Show when={!isSmallScreen()}>
							<div class="filigree-h4-left mt-3" />
						</Show>
						<AudioContextProvider segment="LeaderSelectContinue">
							<HeroButton2
								class={`flex-auto min-w-auto ${isSmallScreen() ? "mx-4" : ""}`}
								onActivate={() => flowContext.activateNext()}
							>
								<div class="font-fit-shrink">
									<L10n.Compose text="LOC_GENERIC_SELECT" />
								</div>
							</HeroButton2>
						</AudioContextProvider>
						<Show when={!isSmallScreen()}>
							<div class="filigree-h4-right mt-3" />
						</Show>

						<div class="leader-select-corner-filigree top-left" />
						<div class="leader-select-corner-filigree top-right" />
						<div class="leader-select-corner-filigree bottom-left" />
						<div class="leader-select-corner-filigree bottom-right" />
					</div>
				</div>
			</Show>
			<div class="absolute top-0 w-full flex items-center justify-center">
				<div class="leader-select-leaders-panel-filigree" />
			</div>
			<div class="absolute bottom-0 w-full flex items-center justify-center">
				<div class="leader-select-leaders-panel-filigree -scale-y-100" />
			</div>
			<Scene3d name="leaderLighting">
				<ModelGroup3d name="CivDetails3dLightingModelGroup">
					<Model3d model="LEADER_LIGHTING_SCENE_CHAR_SELECT_GAME_ASSET" />
				</ModelGroup3d>
			</Scene3d>
		</div>
	);
};

const LeaderSelectDetailsPage1: Component = () => {
	const leaderModel = LeaderSelectModel.get();
	const leader = createMemo(() => leaderModel.selectedLeader());

	return (
		<>
			<div class="leader-select-divider my-2" />
			<div class="flex uppercase leader-select-details-page1">
				<For each={leader().tags}>
					{(attribute) => (
						<div class="font-sm mr-5 flex flex-row items-center ">
							<AttributeIcon
								class="size-8 mr-2"
								attribute={attribute}
							/>
							<div class="font-fit-shrink max-w-48">
								<L10n.Compose text={attribute} />
							</div>
						</div>
					)}
				</For>
			</div>
			<div class="leader-select-divider my-2" />
			<Show when={leader().introText}>
				<L10n.Stylize text={leader().introText} />
			</Show>
			<div class="leader-select-divider my-3" />
			<div class="flex flex-col uppercase text-tertiary-1 font-title font-bold">
				<L10n.Compose text={leader().abilityTitle} />
			</div>
			<div class="text-sm mb-2 uppercase">
				<L10n.Compose text="LOC_UI_CREATE_GAME_LEADER_ABILITY" />
			</div>
			<L10n.Stylize
				class="w-full create-game-markup mb-2"
				text={leader().abilityText}
			/>
		</>
	);
};

const LeaderSelectDetailsPage2: Component = () => {
	const leaderModel = LeaderSelectModel.get();
	const leader = createMemo(() => leaderModel.selectedLeader());

	const isOfflineMemento = !Network.supportsSSO() && Online.Metaprogression.supportsMemento();

	const rewardDesc = createMemo(() => {
		const reward = leader().nextReward;
		if (!reward) {
			return undefined;
		}

		// TODO: This should use a more robust lookup
		const rewardType = getRewardType(reward.gameItemID);
		return rewardType == UnlockableRewardType.Memento
			? `LOC_${reward.gameItemID}_FUNCTIONAL_DESCRIPTION`
			: undefined;
	});

	return (
		<>
			<div class="leader-select-divider my-2" />
			<div class="font-title text-tertiary-1 uppercase">
				<L10n.Compose text="LOC_CREATE_GAME_AGE_UNLOCK_TITLE" />
			</div>
			<div class="text-sm">
				<L10n.Stylize text="LOC_CREATE_GAME_AGE_UNLOCK_SUBTITLE" />
			</div>
			<div class="mt-2">
				<For each={leader().ageUnlocks}>
					{(unlock) => (
						<div class="flex flex-row flex-wrap w-full">
							<span>• </span>
							<L10n.Stylize
								class="create-game-markup tight mb-1"
								text={unlock}
							/>
						</div>
					)}
				</For>
			</div>
			<Show when={leader().syncretismUnlocks.length > 0}>
				<div class="font-title text-tertiary-1 uppercase mt-3">
					<L10n.Compose text="LOC_CREATE_GAME_UNLOCK_ITEM_SYNCRETISM_TITLE" />
				</div>
				<div class="text-sm">
					<L10n.Stylize text="LOC_CREATE_GAME_UNLOCK_ITEM_SYNCRETISM_DESCRIPTION" />
				</div>
				<div class="mt-2 flex flex-col items-start">
					<For each={leader().syncretismUnlocks}>
						{(unlock) => (
							<div class="flex flex-row flex-wrap w-full">
								<SyncretismTooltip
									initialHPosition={TooltipHorizontalPosition.RIGHT}
									initialVPosition={TooltipVerticalPosition.BOTTOM}
									offset={10}
									civilizationType={unlock.civilization}
								>
									<L10n.Stylize
										class="create-game-markup tight mb-1"
										classList={{
											"faux-tooltip-controller": !IsControllerActive(),
										}}
										text={unlock.description}
									/>
								</SyncretismTooltip>
							</div>
						)}
					</For>
				</div>
			</Show>
			<Show when={leader().nextReward && !isOfflineMemento}>
				<div class="leader-select-divider my-3" />
				<div class="flex flex-row flex-wrap">
					<div class="font-title text-tertiary-1 uppercase flex flex-row">
						<L10n.Compose text="LOC_UI_RADIAL_MENU_DETAILS_UNLOCK_NEXT" />
						{":"}
					</div>
					<div class="text-accent-2 ml-1 flex flex-row uppercase">
						<L10n.Compose
							text="LOC_END_GAME_ADD_LEVEL"
							args={[leader().nextReward?.level ?? ""]}
						/>
					</div>
				</div>
				<TicketBox class="flex-auto flex flex-row relative mt-1 overflow-hidden">
					<div class="img-tag-locked absolute left-0 top-5 flex flex-row items-start justify-start">
						<div class="img-lock2 size-8 mt-0\.5 ml-0\.5" />
					</div>
					{/* TODO: This is currently hidden - add back when we can clip the corners properly */}
					{/* <Icon
						class="absolute -left-26 -top-14 opacity-5 size-64"
						name={`url('${leader().nextReward?.reward}')`}
						isUrl={true}
					/> */}
					<div class="flex flex-col items-center justify-center">
						<Icon
							class="size-19 m-4"
							name={`url('${leader().nextReward?.reward}')`}
							isUrl={true}
						/>
					</div>
					<div class="flex flex-col flex-auto ml-2">
						<div class="text-accent-5 font-title text-base">
							<L10n.Compose text={leader().nextReward?.title ?? ""} />
						</div>

						<L10n.Stylize
							class="flex-auto create-game-markup"
							text={rewardDesc() ?? leader().nextReward?.desc ?? ""}
						/>

						<Show when={rewardDesc()}>
							<div class="bg-primary-2 w-full -mr-2 h-0\.5" />
							<L10n.Stylize
								class="text-accent-5 text-sm my-1"
								text={leader().nextReward?.desc ?? ""}
							/>
						</Show>
					</div>
				</TicketBox>
			</Show>
		</>
	);
};

const LeaderSelectDetails: Component = () => {
	const leaderModel = LeaderSelectModel.get();
	const leader = createMemo(() => leaderModel.selectedLeader());

	return (
		<div class="leader-select-leader-details flex flex-col mt-8 flex-auto w-full text-primary-1">
			<div class="h-fit">
				<Header class="leader-select-leader-name text-custom font-bold uppercase leading-none">
					<L10n.Compose text={leader().name} />
				</Header>
			</div>
			<Show when={leader().leaderID != "RANDOM"}>
				<Tab class="flex flex-col flex-auto">
					<ScrollArea
						class="flex-auto"
						useProxy={true}
					>
						<Tab.Output />
					</ScrollArea>
					<CreateGameTabPips />

					<Tab.Item
						name="leader-page=1"
						title={() => "Leader Abilities"}
						body={() => <LeaderSelectDetailsPage1 />}
					/>
					<Tab.Item
						name="leader-page-2"
						title={() => "Leader Unlocks"}
						body={() => <LeaderSelectDetailsPage2 />}
					/>
				</Tab>
			</Show>
		</div>
	);
};

const TRIGGER_ANIMATION_END = WorldUI.hash("AnimationStateChange");

const LeaderStates = {
	Idle: "IDLE_CharSelect",
	VO: "VO_CharSelect",
};

const LeaderSelectScreenComponent: Component = () => {
	const leaderModel = LeaderSelectModel.get();
	const [debouncedLeader, setLeader, isLeaderChanging] = createDebouncedSignal<LeaderInfo>(
		60,
		leaderModel.selectedLeader(),
	);
	const [voPlaying, setVoPlaying] = createSignal(false);
	const leaderState = createMemo(() => (voPlaying() ? LeaderStates.VO : LeaderStates.Idle));
	let voJustStarted = false;

	const subtitlesVisible = createMemo(
		() => Sound.getSubtitles() && voPlaying() && leaderModel.selectedLeader().quote != "",
	);
	const context = useScreenFlowContext();

	// Update leader with debouncing
	createEffect(
		on(
			() => leaderModel.selectedLeader(),
			(leader) => {
				setLeader(leader);
				setVoPlaying(false);
			},
		),
	);

	createEffect(
		on(
			() => debouncedLeader(),
			() => {
				voJustStarted = true;
				setVoPlaying(true);
			},
		),
	);

	function handleModelTrigger(hash: number) {
		if (hash == TRIGGER_ANIMATION_END && !isLeaderChanging()) {
			// There is a delay after an animation changes - so ignore animation ends for a frame after the vo starts
			if (voJustStarted) {
				waitForLayout(() => {
					voJustStarted = false;
				});

				return;
			}

			setVoPlaying(false);
		}
	}

	return (
		<CreateGameStage
			addTextBgGradient={true}
			header={
				<CreateGameStageHeader
					showSteps={!(ViewExperience() == UIViewExperience.Handheld)}
					title="LOC_UI_CREATE_GAME_LEADER_SELECT"
					onBack={() => {
						context.activatePrev();
						//reset filters
						resetCivsFilters();
					}}
				/>
			}
		>
			<div class="size-full relative">
				<LeaderSelectLeadersPanel />
				<LeaderSelectDetails />
				<Show when={subtitlesVisible()}>
					<div
						data-name="subtitles"
						class="create-game-subtitles absolute bottom-2 text-xl text-accent-2 font-title font-black p-2"
					>
						<L10n.Compose text={leaderModel.selectedLeader().quote} />
					</div>
				</Show>
				<Scene3d name="leader">
					<Camera3d
						cameraPos={{ x: -1.834, y: -23.0713, z: 15.2 }}
						subjectPos={{ x: -3.7, y: -17.4867, z: 14.8042 }}
						fov={43}
					/>
					<ModelGroup3d name="CivDetails3dModelGroup">
						<Model3d
							model="LEADER_SELECTION_PEDESTAL"
							angle={120}
							scale={0.9}
						/>
						<Model3d
							hidden={isLeaderChanging()}
							model={debouncedLeader().model}
							state={leaderState()}
							onTrigger={handleModelTrigger}
							clearTemporalHistoryOnChange={true}
						/>
					</ModelGroup3d>
				</Scene3d>
			</div>
		</CreateGameStage>
	);
};

export const LeaderSelectScreen = ComponentRegistry.register({
	name: "leader-select-screen",
	createInstance: LeaderSelectScreenComponent,
	styles: [style],
});

function resetCivsFilters() {
	const ageFilter = createAgeFilterModel();

	ageFilter.reset();
	attrFilter.reset();
}
